// Round 13 (2026-09-07): build sweep/section-dnd.md from sweep/section-dnd.r12.md by exact-string replacement.
// Every replacement must match exactly once (or the count given); a miss aborts the build. Run from the prose-research directory:
//   node sweep/_r13-apply.mjs
// Inputs: section-dnd.r12.md (the round-12 section, preserved), state-dnd.json, partial-dnd.json, sweep/_r13-coverage.mjs's table (embedded below after being run).
import { readFileSync, writeFileSync } from 'node:fs';
const src = readFileSync('sweep/section-dnd.r12.md', 'utf8');
const st = JSON.parse(readFileSync('sweep/state-dnd.json', 'utf8'));
const partial = JSON.parse(readFileSync('sweep/partial-dnd.json', 'utf8'));
let text = src;
let applied = 0;
function rep(oldS, newS, count = 1) {
  const n = text.split(oldS).length - 1;
  if (n !== count) throw new Error(`expected ${count} match(es), found ${n} for: ${oldS.slice(0, 120)}`);
  text = text.split(oldS).join(newS); applied++;
}
function repLine(prefix, newLine) {
  const lines = text.split('\n'); const idx = lines.findIndex(l => l.startsWith(prefix));
  if (idx < 0) throw new Error('no line starts with ' + prefix);
  if (lines.findIndex((l, i) => i > idx && l.startsWith(prefix)) >= 0) throw new Error('more than one line starts with ' + prefix);
  lines[idx] = newLine; text = lines.join('\n'); applied++;
}

